const premiumFor = (quote: QuoteStep): number => {
  const policyBase = policyBasePremiumOf(quote.items);
  // Policy-scoped surcharges apply to the policy base only; item-scoped
  // surcharges are added afterwards and never widen that base.
  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_SURCHARGE;
  return Math.ceil(
    policyBase + itemSurchargesOf(quote.items) + firstInsuranceSurcharge + PROCESSING_FEE,
  );
};
